import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"kiwa v1.19 released — Framework 深化 (SolidJS Signal + Deno Fresh Islands + HonoJS Cloudflare Workers)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.19/gh-discussions-announcement.md","filePath":"announcements/v1.19/gh-discussions-announcement.md"}'),d={name:"announcements/v1.19/gh-discussions-announcement.md"};function r(n,e,c,i,l,p){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="kiwa-v1-19-released-—-framework-深化-solidjs-signal-deno-fresh-islands-honojs-cloudflare-workers" tabindex="-1">kiwa v1.19 released — Framework 深化 (SolidJS Signal + Deno Fresh Islands + HonoJS Cloudflare Workers) <a class="header-anchor" href="#kiwa-v1-19-released-—-framework-深化-solidjs-signal-deno-fresh-islands-honojs-cloudflare-workers" aria-label="Permalink to &quot;kiwa v1.19 released — Framework 深化 (SolidJS Signal + Deno Fresh Islands + HonoJS Cloudflare Workers)&quot;">​</a></h1><p>v1.19 is out. After v1.18&#39;s Blockchain 深化 vertical (<code>kiwa-test-rs</code> v0.5 with Reth EL client integration + Foundry-rs invariant/fuzz depth + Alloy encoder helpers + <code>@kiwa/dapp</code> reorg helpers), v1.19 turns to <strong>modern web framework horizontal expansion</strong> — SolidJS (Signal-based fine-grained reactivity), Deno Fresh (Islands architecture + partial hydration), and HonoJS (Cloudflare Workers + hc RPC type-safe client + middleware chain) — three new packages that lift kiwa web framework coverage from <strong>8 to 11</strong>.</p><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><ul><li><strong><code>@kiwa/solidjs</code> v0.1.0</strong> (new package). Signal-based fine-grained reactivity testing pattern for SolidJS. <code>createSignal(initial)</code> returns a <code>[getter, setter]</code> pair with auto-tracking dependency graph mock; <code>createEffect(fn)</code> schedules effect runs against a deterministic <code>flushSync()</code> scheduler (no real microtask queue); <code>createResource(fetcher)</code> produces a Suspense-boundary-aware async signal with <code>loading</code> / <code>error</code> / <code>latest</code> states; <code>renderComponent(Component, props)</code> mounts the component into a lightweight virtual tree that the assertion API (<code>getByText</code> / <code>getByRole</code> / <code>queryAll</code>) exercises without a running SolidJS runtime. Ships with <code>SuspenseBoundary</code> capture (<code>captureFallback</code> returns the fallback markup during the loading phase, <code>resumeSuspense(id)</code> transitions the boundary to <code>resolved</code>). 42 behavior tests pass (<code>signal.test.ts</code> + <code>route.test.ts</code> + <code>render.test.ts</code> + <code>docs-tutorial-v1.19.test.ts</code>). Framework-agnostic MockNode tree reused from the <code>@kiwa/component</code> v0.1 foundation.</li><li><strong><code>@kiwa/fresh</code> v0.1.0</strong> (new package). Deno Fresh Islands architecture testing pattern. <code>defineRoute</code> normalizes route handler shape to <code>{ handler, component }</code> matching Fresh&#39;s convention; <code>Handler</code> union mock (<code>Handler&lt;Data&gt; | HandlerContext&lt;Data&gt;</code>) exposes <code>req</code> / <code>params</code> / <code>state</code> / <code>render</code> without a Deno runtime; <code>renderIsland(Island, props)</code> mounts an island into the virtual tree with <code>mountBoundary</code> metadata (island name + hydration scope); <code>Head</code> fragment merger accumulates <code>&lt;meta&gt;</code> / <code>&lt;title&gt;</code> / <code>&lt;link&gt;</code> across nested layouts and returns the deduplicated fragment tree. <code>partialHydration</code> helper asserts that server-first rendered markup includes only the interactive island scripts (no full-page bundle). 58 behavior tests pass (<code>islands.test.ts</code> + <code>route.test.ts</code> + <code>head.test.ts</code> + <code>docs-tutorial-v1.19.test.ts</code>). Deno-shape typing preserved (does not depend on the Deno runtime — assertions run on Node.js / Bun / Vitest as long as the caller provides serializable input).</li><li><strong><code>@kiwa/hono</code> v0.1.0</strong> (new package). HonoJS Cloudflare Workers testing pattern. <code>createApp()</code> returns a HonoLike stub with <code>.get / .post / .put / .delete / .patch / .all / .use</code> matching the Hono router surface; <code>app.request(path, init)</code> invokes the handler chain without a real Workers runtime (fetch API polyfill via <code>Request</code> / <code>Response</code> shims); <code>hc&lt;AppType&gt;(baseUrl)</code> produces a type-safe RPC client mock that preserves the <code>AppType</code> inference chain end-to-end (<code>hc&lt;typeof app&gt;(&#39;...&#39;)[&#39;api&#39;][&#39;users&#39;][&#39;:id&#39;].$get({param: {id: &#39;1&#39;}})</code>); <code>middlewareChain([cors, bearerAuth, logger])</code> exposes chain execution order + context state via a <code>MiddlewareTrace</code> shape; <code>mockEnv({ KV: { get, put }, D1: prepareStub, R2: bucketStub })</code> provides the Workers <code>env</code> binding surface for KV, D1, R2, and <code>ExecutionContext</code> (<code>waitUntil</code> / <code>passThroughOnException</code>). 89 behavior tests pass (<code>app.test.ts</code> + <code>workers.test.ts</code> + <code>rpc.test.ts</code> + <code>docs-tutorial-v1.19.test.ts</code>). Pure TypeScript — no <code>wrangler</code> / <code>miniflare</code> runtime dependency at test time.</li><li><strong><code>examples/dogfood-solidjs-signal-app</code></strong> — SolidJS + <code>createResource</code> + Suspense + fine-grained update. <code>makeMockAdapter</code> composes signals with the <code>@kiwa/solidjs</code> deterministic scheduler (all effects fire synchronously via <code>flushSync</code>), <code>makeRealAdapter</code> uses a lightweight SolidJS-like runtime harness. <code>SignalFidelityReport</code> compares mock vs real behavior across 5 scenarios (setter → effect fires / getter reactivity chain / <code>createMemo</code> cache / <code>createResource</code> loading → resolved transition / Suspense boundary fallback → resumed). 7-axis release gate verdict PASS.</li><li><strong><code>examples/dogfood-fresh-islands</code></strong> — Deno Fresh + Islands + partial hydration + edge runtime. <code>makeMockAdapter</code> uses <code>@kiwa/fresh</code> to render a marketing page with 3 islands (<code>CounterIsland</code>, <code>NewsletterIsland</code>, <code>SearchIsland</code>) — captures the mount boundary set and the SSR-rendered HTML skeleton; <code>makeRealAdapter</code> boots a minimal Deno-shaped runtime. <code>IslandsFidelityReport</code> compares mock vs real behavior across 5 scenarios (island mount count / partial hydration markup / <code>defineRoute</code> handler branch / <code>Head</code> fragment merge / SSR-first output). 7-axis release gate verdict PASS.</li><li><strong><code>examples/dogfood-hono-workers-rpc</code></strong> — Cloudflare Workers + Hono RPC type-safe + middleware chain + KV/D1/R2 bindings. <code>makeMockAdapter</code> uses <code>@kiwa/hono</code> <code>createApp()</code> + <code>mockEnv({ KV, D1, R2 })</code> + <code>hc</code> type-safe client; <code>makeRealAdapter</code> uses a Workers-shaped runtime with <code>Request</code> / <code>Response</code> polyfills. <code>HonoFidelityReport</code> compares mock vs real across 5 scenarios (<code>app.request</code> handler dispatch / <code>hc&lt;AppType&gt;</code> type inference preservation / middleware chain execution order / <code>env.KV.get/put</code> binding call / <code>env.D1.prepare(...).all()</code> prepared statement). 7-axis release gate verdict PASS.</li><li><strong>docs</strong> — 3 new tutorials (28 SolidJS Signal + Effect + Resource + Suspense / 29 Fresh Islands + Route Handler + Head normalize / 30 HonoJS + hc RPC + middleware + KV/D1/R2) + additive migration guide v1.18 → v1.19 + concept doc <code>modern-web-framework-testing.md</code> documenting the <strong>3 additional axes × 6 semantic axes</strong> (Signal reactivity (fine-grained dependency graph + effect scheduler) / Islands architecture (partial hydration + island boundary detection + Head normalize) / Edge runtime + RPC type-safety (Workers env binding + hc type inference preservation + middleware chain)) as the SSOT. VitePress sidebar refreshed with a new <code>Framework 深化 (v1.19)</code> tutorial section; gh-pages published via <code>/docs-publish-kiwa</code>.</li></ul><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><ul><li><strong>6 sub-Issues resolved</strong> (#807-#812)</li><li><strong>6 PRs merged</strong> (v1.19-1a/b/c + v1.19-2/3/4/5 + this publish PR)</li><li><strong>3 new npm packages</strong> (<code>@kiwa/solidjs</code> v0.1.0 + <code>@kiwa/fresh</code> v0.1.0 + <code>@kiwa/hono</code> v0.1.0) — kiwa runtime fixture count now <strong>33</strong></li><li><strong>3 new dogfood apps</strong> with fidelity reports feeding the 7-axis release gate</li><li><strong>189 new tests</strong> across the 3 packages (42 + 58 + 89) all pass</li></ul><h2 id="_9-milestone-streak" tabindex="-1">9-milestone streak <a class="header-anchor" href="#_9-milestone-streak" aria-label="Permalink to &quot;9-milestone streak&quot;">​</a></h2><p>v1.11 (release gate) → v1.12 (non-determinism) → v1.13 (time-axis) → v1.14 (horizontal expansion) → v1.15 (AI-LLM depth) → v1.16 (component depth) → v1.17 (Observability v2) → v1.18 (Blockchain depth) → <strong>v1.19 (Framework 深化)</strong>. Every milestone since v1.11 has landed 6 sub-Issues in full.</p><h2 id="v2-0-candidates" tabindex="-1">v2.0 candidates <a class="header-anchor" href="#v2-0-candidates" aria-label="Permalink to &quot;v2.0 candidates&quot;">​</a></h2><ul><li>Multi-version Vitest matrix (Vitest 1.x vs 2.x vs 3.x parity)</li><li>Desktop (Electron / Tauri) + mobile (React Native / Expo) adapters</li><li>Coverage 100% milestone</li><li>Cache / Data depth (Dragonfly / Materialize / Neon)</li><li>L2 depth (Base / Arbitrum / Optimism / Scroll block-space fidelity)</li><li>ZK depth (Noir / Circom / RISC Zero test harness)</li></ul><p>Feedback welcome on which of these should land next.</p>',11)])])}const m=o(d,[["render",r]]);export{u as __pageData,m as default};
